export const meta = {
  name: 'treams-rs-open-source-stage',
  description: 'Run one stage of the open-source readiness plan: lanes in parallel, each work package implemented, adversarially reviewed and fixed in its lane worktree',
  phases: [
    { title: 'Implement', detail: 'one agent per work package inside its lane worktree' },
    { title: 'Review', detail: 'adversarial review against the plan, the glossary and the gate profile' },
    { title: 'Fix', detail: 'address review findings, re-verify' },
  ],
}

const R4 = 'wps/round4'
const TRAILER = 'Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\nClaude-Session: [link to a conversation in the cloud]'

const CONTEXT = `
PROJECT: treams-rs — a T-matrix electromagnetic scattering package: Rust numerical core (crates/treams-core) with analytic pullbacks, PyO3 bindings (crates/treams-py -> treams_rs._native, stub python/treams_rs/_native.pyi), a typed physics-first Python API (python/treams_rs) with Advect/JAX/PyTorch adapters, Rust unit + proptest tests, a pytest + Hypothesis suite (tests/), docs (docs/), scripts/, benchmarks/ (evidence), formal/ (Lean golden values). Upstream treams (the reference package) is at scratch: treams (commit 1f5d0d6), installed as treams 0.4.5 in the venv.

THIS ROUND: open-source readiness. Owner's goal: modules with clear responsibilities, good naming, concise but meaningful comments wherever things are not obvious (and no comments narrating history or process), everything fully self-consistent across Rust, bindings, Python, tests and docs, better abstractions wherever possible, and well-organized docs (MkDocs site on GitHub Pages) with examples and rationale for people who know treams. NO numerical change: every refactor is bitwise identical and perf-neutral.

BINDING DOCUMENTS — read before anything else:
1. ${R4}/decisions.md (owner decisions, lead defaults, out of scope, hard gates).
2. ${R4}/plan.md: §2 principles, §4 glossary (one name per concept — authoritative for every name), §5 naming rules, §8 gates, tools and gate profiles, §9 hot spots and routing (and §6/§7 for the target trees and the public rename list when your package needs them).
3. Your work package file ${R4}/wp/<ID>.json: brief (authoritative scope and steps), files_owned, gate_profile, acceptance, risk.
Line numbers in briefs refer to 5fe22f4; earlier packages have moved code since, so locate items by name and verify every claim against the code (git log shows what earlier packages did).

HARD RULES:
- Edit only the package's files_owned. If a change outside them is unavoidable, make the minimal change only when it is a mechanical consequence of your package (e.g. an import path or a renamed call site that would otherwise not compile/run) and list every such file in open_issues; anything more goes to open_issues undone.
- Keep every feature, every test (moves/renames are fine with GATE-RT/GATE-IDS evidence), every #[inline]/#[inline(always)]/#[inline(never)] attribute, closure capture pattern, monomorphization and float-reduction order. Never loosen a tolerance, weaken a property or regenerate the parity baseline. Never touch benchmarks/results/**, parity, treams (Python original)**, the main checkout treams-rs, or other worktrees under scratch: lanes.
- Rust lints are strict (clippy all+pedantic+nursery -D warnings, missing_docs, unreachable_pub; edition 2024, toolchain 1.94); Python: ruff format + lint, strict pyrefly.
- Generated files (docs/api.md or docs/reference/python/**, llms.txt, generated regions) are regenerated with \`wt.sh docs\`, never hand-edited. CHANGELOG.md: append bullets at the end of the matching '## [Unreleased]' subsection only (merge=union).
- Lean-modelled functions (formal/: diffraction orders in geometry, lattice shells, translation selection rules, LU equilibration, the requested-illumination pullback) keep their semantics; cargo tests compare them with formal/golden files; keep formal/README.md names valid or update them if your package owns it.
- Comments and docs: present-tense rationale; no "previously/now/fixed/round/review/lane/revision/maintenance pass", no local paths, no process narration.
`

const TOOLING = (w) => `
TOOLING — run from inside the worktree; every Bash call starts in a fresh shell, so always \`cd ${w} && ...\`. Use scratch: wt.sh for every build, test and gate (run \`scratch: wt.sh help\` or read the script for the full command list): build-ext, rust-test [filter], rust-lint, rust-fmt, rust-doc, rust-doc-private, rust-test-list, pytest <args>, ids, py-fmt, py-lint, py-types, docs, docs-check, docs-build, docs-rust, docs-examples, lock, parity, bitwise [--battery PATH], uf, lat, hot, kit-copy, kit-diff <ID>, perf-ab <workload> [args], perf-cg <fwd|bwd> <workload> [args], perf-illum, gates, full.
- uv 0.12.3 lives at /usr/local/bin/uv (an older uv shadows it on the default PATH): run the lock command as \`PATH=/usr/local/bin:$PATH scratch: wt.sh lock [--check]\`.
- Never use just, uv run, uv sync, pip or maturin directly (they modify the shared venv or rebuild everything); \`wt.sh lock\` is the only way to touch uv.lock.
- cargo/pytest are pinned to CPUs 0-2; CPU 3 belongs to the perf station. The machine has 4 CPUs shared by three lanes: avoid needless rebuilds; build-ext reuses the merge-point extension automatically when your lane has not changed crates/.
- Performance: never build release in the lane. \`wt.sh perf-ab\` / \`perf-cg\` / \`perf-illum\` check out your committed HEAD in the perf station, build release there under a lock (expect waiting) and compare with the reference build treams (Python original): r4 (5fe22f4). Commit first, then measure.
- Bitwise gates: \`wt.sh bitwise\` (battery at 1 thread vs r4.npz, tolerance 0), \`wt.sh uf\` / \`lat\` / \`hot\` (ufunc/record/fast-path, lattice and hot-path dumps vs the r4 recordings through the gate kit's key/message map). If your package renames Python-visible or native names or changes messages: \`wt.sh kit-copy\`, adapt ONLY call sites/names (never inputs or keys) in the lane-local kit copy plus its map.json, run the gates with that copy (\`wt.sh bitwise --battery <copy>/battery.py\`, and the uf/lat/hot equivalents per the kit README), then \`wt.sh kit-diff <ID>\` to write the patch the lead folds in. Gate kit README: ${R4}/gates/current/README.md.
- Measurement caveats (from the tooling's calibration): perf-ab pair medians of the SAME commit vary up to ~4% while lanes compile on CPUs 0-2, so a single >3% A/B reading is not proof of a slowdown: rerun it, and treat it as real only if it repeats AND perf-cg shows an instruction-count increase on the same workload (otherwise report it for the lead's quiet-window re-measurement). perf-cg forward counts are exactly reproducible for the same commit; backward counts vary by ~0.1%. Run the battery and dumps only through wt.sh (it pins BLAS to one thread; under 3-CPU pinning a multi-threaded OpenBLAS changes last bits).
- GATE-RT (Rust test identity): \`wt.sh rust-test-list\` before your first change and at the end; same multiset of test names modulo the module-path map you document in the commit body. GATE-IDS (Python test identity): \`wt.sh ids\` before and after; identical modulo your documented rename map; skip count unchanged unless documented.
`

const COMMIT_RULES = `
COMMITS: small logical commits, each building and passing its focused tests. Conventional subject (feat|fix|perf|refactor|test|docs|build|chore: imperative summary <= 72 chars), a body explaining what and why (for moves: the old -> new path map; for renames: the old -> new name map; for test moves: the GATE-RT/GATE-IDS map), ending with exactly these two trailer lines (they replace the trailers quoted in decisions.md and the briefs):
${TRAILER}
Write multi-line messages to a file under scratch and use \`git commit -F <file>\`. Never amend/rebase/reset commits you did not create in this session, never push, never create branches. Finish with a clean \`git status\`.
`

const IMPL = {
  type: 'object',
  properties: {
    wp: { type: 'string' },
    base_sha: { type: 'string', description: 'HEAD before your first change' },
    head_sha: { type: 'string', description: 'HEAD after your last commit' },
    commits: { type: 'array', items: { type: 'object', properties: { sha: { type: 'string' }, subject: { type: 'string' } }, required: ['sha', 'subject'] } },
    implemented: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, summary: { type: 'string' } }, required: ['id', 'summary'] } },
    skipped: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
    verification: { type: 'string', description: 'exact commands run at the end and their results: the gate profile gates, the acceptance checks, test counts, bitwise/dump summaries, GATE-RT/GATE-IDS results, lint status' },
    performance: { type: 'string', description: 'perf-cg/perf-ab results with workloads, or "none required"' },
    kit_patch: { type: 'string', description: 'path of the gate-kit patch written with wt.sh kit-diff, or "none"' },
    outside_files: { type: 'string', description: 'files changed outside files_owned and why, or "none"' },
    loc_delta: { type: 'string', description: 'git diff --shortstat base..head' },
    open_issues: { type: 'string', description: 'anything left unfinished, risky or out of scope' },
  },
  required: ['wp', 'base_sha', 'head_sha', 'commits', 'implemented', 'skipped', 'verification', 'performance', 'kit_patch', 'outside_files', 'loc_delta', 'open_issues'],
}

const REVIEW = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['approve', 'changes_required'] },
    summary: { type: 'string' },
    checks_run: { type: 'string', description: 'commands you ran and their results' },
    issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          location: { type: 'string' },
          problem: { type: 'string' },
          required_fix: { type: 'string' },
        },
        required: ['severity', 'location', 'problem', 'required_fix'],
      },
    },
  },
  required: ['verdict', 'summary', 'checks_run', 'issues'],
}

const LIGHT = ['move', 'tests', 'docs']
const wpFile = (wp) => `${R4}/wp/${wp.id}.json`

const implPrompt = (lane, wp) => `You are a senior Rust/Python numerical engineer implementing work package ${wp.id} ("${wp.title}") of the treams-rs open-source readiness plan.

WORKTREE: ${lane.worktree} (git branch ${lane.branch}). Do ALL edits, builds, tests and commits there.
${wp.resume_base ? `RESUMING AN INTERRUPTED PACKAGE: a previous engineer started this package at ${wp.resume_base} and was stopped by an infrastructure limit (not by a problem in the work). Their commits ${wp.resume_base}..HEAD belong to this package — read \`git log --stat ${wp.resume_base}..HEAD\` first. Uncommitted changes in the worktree are their unfinished step: understand it, then finish, verify and commit it if sound, or revert just those files if not. Report base_sha = ${wp.resume_base} and cover the whole package.` : 'Record `git rev-parse HEAD` before your first change as base_sha, and record the "before" baselines your gate profile needs (rust-test-list / ids) before changing anything.'}
${CONTEXT}${TOOLING(lane.worktree)}${COMMIT_RULES}
YOUR PACKAGE: ${wpFile(wp)} (read it completely; use python3 -c 'import json; ...' if it is large). Its gate_profile names the gates you must pass (plan §8.2) and its acceptance lists the package-specific checks.

HOW TO WORK:
1. Read the binding documents, then the code you will change. Verify every claim of the brief; adapt where the code differs from the brief's assumptions (earlier packages may have renamed or moved things), staying faithful to the plan's names and structure. Record deviations with reasons in skipped/open_issues.
2. Work in the order the brief gives (moves, then renames, then abstractions), committing each logical step. For moves use git mv so history follows, and keep bodies byte-identical where the brief says so (check with \`git diff --color-moved=zebra -M\`).
3. Keep every renamed name consistent everywhere it appears in your owned files: code, stubs, tests, docs fences, comments, CHANGELOG. Grep for old names before finishing.
4. Run your gate profile's gates and every acceptance check at the end, fix everything until green, and report exact results. Profile 'move': perf-cg on the listed kernels is the arbiter. Profile 'refactor': perf-cg and perf-ab both gate. Profile 'python-api': bitwise with the adapted kit. Profile 'tests': GATE-RT/GATE-IDS. Profile 'docs': GATE-DOCS.
5. Stay within the package scope; put valuable out-of-scope observations in open_issues.`

const reviewPrompt = (lane, wp, impl, round) => `You are an adversarial senior reviewer (round ${round}) for work package ${wp.id} "${wp.title}" of the treams-rs open-source readiness plan.
The implementer worked in ${lane.worktree} (branch ${lane.branch}) from ${impl.base_sha} to ${impl.head_sha}. Read \`git -C ${lane.worktree} log --stat ${impl.base_sha}..${impl.head_sha}\` and the COMPLETE diff (\`git -C ${lane.worktree} diff -M --color-moved=zebra ${impl.base_sha}..${impl.head_sha}\` helps for moves), plus surrounding code as needed.
${CONTEXT}${TOOLING(lane.worktree)}
Package specification: ${wpFile(wp)}
Implementer report: ${JSON.stringify(impl)}

Check, and try hard to find real problems:
1. Scope: every step of the brief done (or skipped with a sound reason); files changed outside files_owned justified as mechanical consequences; nothing unrelated changed.
2. Behaviour: bitwise identity — run \`wt.sh bitwise\` (with the lane's adapted kit battery if the package renames names) and the dumps the profile requires (\`wt.sh uf\`, \`lat\`, \`hot\`); any numeric difference is HIGH; message/key differences must equal the documented map. For moves/refactors also scan the diff for changed expressions, changed float-reduction order, dropped/added #[inline*], changed closure captures, changed iteration order, changed parallel thresholds: HIGH unless provably equivalent.
3. Performance per the gate profile: rerun the listed perf-cg (instruction counts within ±0.5% of r4) and, for 'refactor', perf-ab (no consistent >3% slowdown; rerun anything >2% once). For 'move', an A/B slowdown with unchanged instruction counts is reported in the summary for the lead, not as an issue.
4. Tests: GATE-RT / GATE-IDS evidence matches (rerun \`wt.sh rust-test-list\` / \`wt.sh ids\` and compare with the documented map); no lost test, assertion, budget, tolerance or proptest seed line (seed rule, plan §9).
5. Naming and self-consistency: every name the package touches follows the plan §4 glossary and §5 rules exactly; old names left anywhere the package owns (code, comments, stubs, tests, docs fences, CHANGELOG) are MEDIUM; grep the whole repository for old names and report leftovers outside owned files for the lead (LOW unless they break something).
6. Quality: module/item docs and comments are accurate, concise, present-tense rationale where not obvious, with 'Upstream:'/'Mirrors' pointers where the plan requires them; no history/process narration; abstractions genuinely simpler; idiomatic Rust/Python; CHANGELOG entries present for public renames/behaviour changes; commit messages accurate with the required maps and trailers.
7. Gates: run \`cd ${lane.worktree} && scratch: wt.sh gates\` and the full pytest (\`scratch: wt.sh pytest -q -x\`), \`wt.sh rust-doc\` and \`wt.sh rust-doc-private\` when Rust docs changed, \`wt.sh docs-build\` when docs changed, and every acceptance item of the package.
Do NOT edit files or commit. Verdict 'approve' only if no high or medium issue remains. For each issue give location, problem and the exact required fix.`

const fixPrompt = (lane, wp, impl, review) => `You are fixing review findings for work package ${wp.id} "${wp.title}" of the treams-rs open-source readiness plan, in ${lane.worktree} (branch ${lane.branch}). Record the current HEAD as base_sha before changing anything.
${CONTEXT}${TOOLING(lane.worktree)}${COMMIT_RULES}
Package specification: ${wpFile(wp)}
Implementer report: ${JSON.stringify(impl)}
Review findings: ${JSON.stringify(review)}
Address every high and medium issue, and low ones when cheap and clearly right. If you believe a finding is wrong, do not change the code for it — explain why in open_issues. Finish with your gate profile's gates and the package acceptance checks green, and report with the same schema (implemented = findings fixed, skipped = findings declined with reasons).`

async function runWP(lane, wp) {
  const impl = wp.impl || await agent(implPrompt(lane, wp), { label: `impl:${wp.id}`, phase: 'Implement', schema: IMPL })
  if (!impl) return { lane: lane.name, wp: wp.id, error: 'implementation agent failed' }
  const rbase = wp.review_base || impl.base_sha
  let last = { ...impl, base_sha: rbase }
  const rounds = []
  for (let round = 1; round <= 3; round++) {
    const review = await agent(reviewPrompt(lane, wp, last, round), { label: `review${round}:${wp.id}`, phase: 'Review', schema: REVIEW })
    if (!review) break
    rounds.push({ review })
    if (review.verdict === 'approve') break
    const fix = await agent(fixPrompt(lane, wp, last, review), { label: `fix${round}:${wp.id}`, phase: 'Fix', schema: IMPL })
    if (!fix) break
    rounds[rounds.length - 1].fix = fix
    last = { ...fix, base_sha: rbase }
    const serious = review.issues.some((i) => i.severity === 'high' || i.severity === 'medium')
    if (!serious) break
    // Pure moves, test-only and docs-only packages: mechanical gates (bitwise, test identity, docs build) back
    // the fix, so a fix of medium findings without any high finding is accepted without another round.
    if (LIGHT.includes(wp.profile) && !review.issues.some((i) => i.severity === 'high')) {
      rounds[rounds.length - 1].accepted_without_rereview = true
      break
    }
  }
  const lastRound = rounds[rounds.length - 1]
  const approved = !!lastRound && (lastRound.review.verdict === 'approve'
    || (!!lastRound.fix && (lastRound.accepted_without_rereview
      || !lastRound.review.issues.some((i) => i.severity === 'high' || i.severity === 'medium'))))
  return { lane: lane.name, wp: wp.id, profile: wp.profile || null, approved, impl, rounds, head_sha: last.head_sha }
}

async function runLane(lane) {
  const out = []
  for (const wp of lane.wps) {
    const result = await runWP(lane, wp)
    out.push(result)
    log(`${lane.name}: ${wp.id} finished at ${result.head_sha || 'n/a'} (${result.approved ? 'approved' : 'NOT approved'})`)
  }
  return out
}

const results = await parallel(args.lanes.map((lane) => () => runLane(lane)))
return results
