const fixPrompt = (lane, wp, impl, review) => `You are fixing review findings for work package ${wp.id} "${wp.title}" of the treams-rs open-source readiness plan, in ${lane.worktree} (branch ${lane.branch}). Record the current HEAD as base_sha before changing anything.
${CONTEXT}${TOOLING(lane.worktree)}${COMMIT_RULES}
